head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > E > ondblclick]<br/>컴포넌트를 마우스 왼쪽 버튼으로 더블 클릭할 때 발생합니다.",
    "validation" : [                
        "CheckCombobox 컴포넌트를 더블 클릭하면 onfocus -> onclick -> onblur -> onfocus -> onclick -> onclose -> ondblclick 순서로 이벤트가 발생합니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onblur", "onclick", "onclose", "ondblclick", "onfocus"]);

    // comp 생성 함수 호출    
    $c.gcm.createBasicCheckComboBox('', eList); 
}



scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onfocus=====");    
}


scwin.target1_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onclick=====");    
}


scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onblur=====");    
}


scwin.target1_onclose = function (closeOut) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onclose=====");    
}


scwin.target1_ondblclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ondblclick=====");    
}
